import React, { useState } from 'react';

function App() {
  const [friends, setFriends] = useState([
    { name: 'Sangavi', balance: -70 },
    { name: 'Max', balance: -180 },
    { name: 'Annie', balance: 10 },
    { name: 'Rajeshwari', balance: 1500 }
  ]);
  const [selected, setSelected] = useState(null);
  const [bill, setBill] = useState('');
  const [yourExp, setYourExp] = useState('');
  const [friendExp, setFriendExp] = useState('');

  function splitBill() {
    const total = parseFloat(bill);
    const yours = parseFloat(yourExp);
    const theirs = parseFloat(friendExp);

    if (isNaN(total) || isNaN(yours) || isNaN(theirs)) {
      alert('Please enter valid numbers for all fields.');
      return;
    }

    if (yours + theirs !== total) {
      alert("Your and friend's expenses must add up to the bill.");
      return;
    }

    if (!selected) {
      alert('Please select a friend to split with.');
      return;
    }

    const youPaidMore = yours - theirs;

    setFriends((prev) =>
      prev.map((f) =>
        f.name === selected ? { ...f, balance: f.balance + youPaidMore } : f
      )
    );

    // Reset form
    setBill('');
    setYourExp('');
    setFriendExp('');
    setSelected(null);
  }

  return (
    <div style={{ padding: '30px', fontFamily: 'sans-serif', maxWidth: '500px', margin: 'auto' }}>
      <h1>🍽️ Bill Splitter App 💸</h1>

      <ul style={{ listStyle: 'none', padding: 0 }}>
        {friends.map((f) => (
          <li key={f.name} style={{ marginBottom: '10px' }}>
            <strong>{f.name}:</strong>{' '}
            {f.balance < 0
              ? `You owe ₹${-f.balance}`
              : f.balance > 0
              ? `${f.name} owes you ₹${f.balance}`
              : 'Settled up'}
            <button
              style={{
                marginLeft: '10px',
                backgroundColor: selected === f.name ? 'green' : 'gray',
                color: 'white',
                border: 'none',
                padding: '5px 10px',
                cursor: 'pointer',
                borderRadius: '5px',
              }}
              onClick={() => setSelected(f.name)}
            >
              {selected === f.name ? 'Selected' : 'Select'}
            </button>
          </li>
        ))}
      </ul>

      {selected && (
        <div style={{ marginTop: '20px' }}>
          <h2>Split a bill with {selected}</h2>

          <input
            type="number"
            placeholder="Total Bill (₹)"
            value={bill}
            onChange={(e) => setBill(e.target.value)}
            style={{ display: 'block', marginBottom: '10px', width: '100%' }}
          />

          <input
            type="number"
            placeholder="Your Expense (₹)"
            value={yourExp}
            onChange={(e) => setYourExp(e.target.value)}
            style={{ display: 'block', marginBottom: '10px', width: '100%' }}
          />

          <input
            type="number"
            placeholder="Friend's Expense (₹)"
            value={friendExp}
            onChange={(e) => setFriendExp(e.target.value)}
            style={{ display: 'block', marginBottom: '10px', width: '100%' }}
          />

          <button
            onClick={splitBill}
            style={{
              backgroundColor: '#007bff',
              color: 'white',
              padding: '10px 20px',
              border: 'none',
              borderRadius: '5px',
              cursor: 'pointer',
            }}
          >
            Split Bill
          </button>
        </div>
      )}
    </div>
  );
}

export default App;
